#include <iostream>
using namespace std;

const int MAX_FUNCIONARIOS = 20;

void preencherSalarios(float salarios[], int numFuncionarios) {
    for (int i = 0; i < numFuncionarios; i++) {
        cout << "Insira o salario do funcionario " << (i + 1) << ": ";
        cin >> salarios[i];
    }
}

void imprimirSalariosAcima(float salarios[], int numFuncionarios, float valorMinimo) {
    cout << "\nSalarios acima de " << valorMinimo << ":\n";
    for (int i = 0; i < numFuncionarios; i++) {
        if (salarios[i] > valorMinimo) {
            cout << "Funcionario " << (i + 1) << ": " << salarios[i] << endl;
        }
    }
}

int main() {
    int numFuncionarios;
    float salarios[MAX_FUNCIONARIOS];
    float valorMinimo;

    cout << "Quantos funcionarios sao? ";
    cin >> numFuncionarios;

    if (numFuncionarios < 1 || numFuncionarios > MAX_FUNCIONARIOS) {
        cout << "Numero invalido de funcionarios! Informe um valor entre 1 e " << MAX_FUNCIONARIOS << ".\n";
        return 1;
    }

    preencherSalarios(salarios, numFuncionarios);
    cout << "\nInforme o valor minimo do salario: ";
    cin >> valorMinimo;

    imprimirSalariosAcima(salarios, numFuncionarios, valorMinimo);
    return 0;
}
