    cout << "Listagem de funcionários cujo salário seja maior que " << valorMinimo << endl;
    bool existeValMin; //guarda true se houver pelo menos um funcionário que ganhe mais que o valorMinimo

    bool acabouLista;
    int salariosMaisQueMin[];
    int numFuncionariosMaisQueMin;
    do{
        while(!acabouLista){
            for(i=0; i<numFuncionarios; i++){
                if(salario[i] > valorMinimo){
                    salariosMaisQueMin[i] = salario[i];
		    numFuncionariosMaisQueMin++;
                }
            }
        }

    }while(!existeValMin);

    if(!existeValMin)
	cout << "Nenhum funcionário possui salário acima de "<< valorMinimo << endl;
    else{
        for(i=0; i<numFuncionariosMaisQueMin; i++){
	    cout << "Funcionário " << i+1 << " com salário " << salariosMaisQueMin[i] << endl;
 	}
    }
}

