void imprimirSalariosAcima(float sal[], int tam, float x) {
    int pes=0;
    int p=1;
    cout << "Listagem de funcionarios cujo salario seja maior que " << x << ":" << endl;
    for (int i = 0; i < tam; i++) {
        if (sal[i] < x) {
            pes++;
        }
    }
    if (pes == tam) {
        cout << "Nenhum funcionario possui salario acima de " << x << endl;
    }
    else {
        for (int i = 0; i < tam; i++) {
            if (sal[i] > x) {
                cout << "Funcionario " << p << " com salario " << sal[i] << " Euros." << endl;
                ++p;

            }
        }
    }
}

