        cin >> salarios[i];
    }
}

// Função para imprimir os salários acima de um valor mínimo
void imprimirSalariosAcima(float salarios[], int numFuncionarios, float valorMinimo) {
    cout << "\nListagem de funcionarios cujo salario seja maior que " << valorMinimo << ":\n";

    bool encontrou = false; // Flag para verificar se há salários acima do valor mínimo

    for (int i = 0; i < numFuncionarios; i++) {
        if (salarios[i] > valorMinimo) {
            cout << "Funcionario " << (i + 1) << " com salario " << salarios[i] << " Euros\n";
            encontrou = true;
        }
    }

    if (!encontrou) {
        // Caso não encontre nada válido flag = false 
        cout << "Nenhum funcionario possui salario acima de " << valorMinimo << ".\n";
    }
}

