void imprimirSalariosAcima(float &salarios, int numFuncionarios, float valorMinimo) {
    cout << "Listagem de funcionarios cujo salario seja maior que " << valorMinimo << "." << endl;
    for (int i = 0; i < sizeof(&salarios)/8; i++) {
        if (&salarios[i]>valorMinimo)
            cout << "Funcionario " << i+1 << " com salario "<< &salarios[i] <<" Euros";
        else
            cout << "Nenhum funcionario possui salario acima de X onde X representa o valor mínimo indicado pelo utilizador";
    }
}

