        cout << "Código Postal: " << pessoas[i].morada.codigoPostal << endl;
        cout << "Localidade: " << pessoas[i].morada.localidade << endl;
    }

    cout << "\nTotal de pessoas registadas: " << n << endl;

    delete[] pessoas;

    return 0;
}

