ios::in: é utilizado quando queremos abrir um arquivo para leitura. Se o arquivo não existir, uma falha ocorre.
e
ios::out: é utilizado quando queremos abrir um arquivo para escrita. Se o arquivo não existir, ele será criado. Se o arquivo já existir, o conteúdo será sobrescrito.


#include <fstream>
#include <iostream>
#include <string>
using namespace std

int main() {
    ifstream arquivo("exemplo.txt", ios::in); 

    if (!arquivo) {  
        cerr << "Erro ao abrir o arquivo." << endl;
        return 1;
    }

    string linha;
    while (getline(arquivo, linha)) {  
         cout << linha << endl;  
    }

    arquivo.close(); 

    return 0;
}

