a) 
nodo* inserirNodo(nodo* raiz, int valor) {
    if (raiz == NULL) {
        nodo* novo = new nodo;
        novo->dados = valor;
        novo->esq = NULL;
        novo->dir = NULL;
        return novo;
    }

    if (valor < raiz->dados)
        raiz->esq = inserirNodo(raiz->esq, valor);
    else
        raiz->dir = inserirNodo(raiz->dir, valor);

    return raiz;
}

b)
bool existe(nodo* raiz, int valor) {
    if (raiz == NULL)
        return false;
    if (raiz->dados == valor)
        return true;
    if (valor < raiz->dados)
        return existe(raiz->esq, valor);
    else
        return existe(raiz->dir, valor);
}

void imprimirFolhas(nodo* raiz) {
    if (raiz == NULL)
        return;
    if (raiz->esq == NULL && raiz->dir == NULL)
        cout << raiz->dados << " ";
    imprimirFolhas(raiz->esq);
    imprimirFolhas(raiz->dir);
}

int somaValores(nodo* raiz) {
