    }
    return nodo;
}


b)


bool PesquisaBST(nodo* raiz, int valor ){
    if ( raiz == NULL )
        return false;
    if ( valor == raiz-> valor )
        return true;
    else if ( valor < raiz-> valor )
        return PesquisaBST( raiz->esquerda, valor );
    else
        return PesquisaBST( raiz->direita, valor );
}

